// Three entry points become one shape. Webhook = system event (alert, driver message). Chat = operator. Follow-up = a person finished a step.
// Every run gets a run id (drafts and the event row carry it). A wake-up names its workflows, so routing is exact.
const run_id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const j = $json;
if (j.chatInput !== undefined) {
  const refs = [...new Set((String(j.chatInput).match(/CD-\d{6}/gi) || []).map((r) => r.toUpperCase()))];
  if (refs.length > 1) return [{ json: { order_ref: '', error: `You named ${refs.join(' and ')}. One order per message, please: which one is this about?` } }];
  return [{ json: { order_ref: refs[0] || '', run_id, kind: 'chat', source: 'operator chat', text: String(j.chatInput), simulate: '', workflows: [] } }];
}
const b = j.body || j;
const ref = String(b.order_ref || '').trim().toUpperCase();
const kind = b.source === 'follow_up' ? 'follow_up' : 'event';
const workflows = String(b.workflows || '').split(',').map((x) => x.trim()).filter(Boolean);
return [{ json: { order_ref: ref, run_id, kind, source: b.source || 'system', text: String(b.event || 'Review this order now.'), simulate: String(b.simulate || ''), workflows } }];

// Step 1 of routing, by code: dataset alert/incident codes named in the event map straight to a workflow.
// Step 2 (next node): GLiDE answers one yes/no question per workflow about the free text.
const CODES = {
  VEHICLE_WARNING: 'vehicle', SAFETY_STOP: 'vehicle',
  FERRY_SOLD_OUT: 'journey', FERRY_CONNECTION_RISK: 'journey', TRAVEL_CAPACITY: 'journey', POSITIONING_AT_RISK: 'journey', DELIVERY_PROMISE_UNACHIEVABLE: 'journey',
  TRACKING_GAP: 'tracking', FERRY_TRACKING_GAP_CONTEXT: 'tracking',
  DELIVERY_ACCESS_RISK: 'destination', SITE_ACCESS_CONFLICT: 'destination', SITE_ACCESS_UNCONFIRMED: 'destination',
  RELEASE_DOCUMENT_UNCLEAR: 'documents', PICKUP_PROOF_REJECTED: 'documents',
  DRIVER_AVAILABILITY_RISK: 'driver_availability', // GLiDE decides: rest (journey) or cannot continue (incident)
};
const Q = {
  vehicle: ['Is there a problem with the car itself: warning light, breakdown, damage, flat tyre, fuel or charge trouble, car will not start, or a stop because of the car?', 'A problem with the car', 'No problem with the car'],
  journey: ['Is the delivery late or at risk of being late, or is a ferry, train or connection missed, sold out or at risk, or must the driver rest (driving-hours limit, tired, mildly unwell) or slow down for traffic or weather?', 'Timing, connection or rest problem', 'No timing problem'],
  destination: ['Is there a problem at the delivery place: no access, closed, nobody to receive the car, wrong or changed address, buyer not available?', 'Problem at the delivery place', 'No delivery place problem'],
  tracking: ["Has the car's tracking or GPS position stopped updating, gone missing, or does it look wrong?", 'Tracking problem', 'Tracking is fine or not mentioned'],
  incident: ["Is this urgent for a person's safety or the car's security: accident, injury, medical emergency, theft, police, threat, or the driver cannot continue the job at all?", 'Urgent safety or security problem', 'Not urgent'],
  documents: ['Is a document missing, unclear or wrong: release note, registration papers, key handover paperwork, proof of pickup or delivery?', 'Document problem', 'No document problem'],
  expenses: ['Is this about money the driver spent or wants back: fuel, charging, parking, tolls, hotel, train or flight receipts, reimbursement?', 'Driver expense', 'Not about driver expenses'],
  driver_cannot_continue: ['Does the driver say they cannot continue this job at all, so a replacement driver is needed (not just a rest or a delay)?', 'Driver cannot continue, replacement needed', 'Driver can continue, maybe after rest'],
};
const n = $('Normalize').first().json;
const c = $json;
const found = Object.keys(CODES).filter((k) => new RegExp(`\\b${k}\\b`).test(n.text));
const glide_body = { model: 'fastino/GLiDE', store: false,
  state: { event: n.text, order_status: c.snapshot?.order?.status || 'unknown' },
  questions: Object.fromEntries(Object.entries(Q).map(([k, [instructions, yes, no]]) => [k, { type: 'noul', instructions, criteria: { true: yes, false: no } }])) };
return [{ json: { codes: found, code_workflows: [...new Set(found.map((k) => CODES[k]))], need_glide: n.kind !== 'follow_up', glide_body } }];

// Step 3: decide which problem workflows run. Rules enforced here, not in prompts:
// - root cause wins: vehicle, documents, destination or incident -> journey is dropped (they call journey themselves if timing is hit)
// - tracking runs alongside the others; journey alone only for a delay with no other cause
// - no double requests: an open case keeps one memory session per workflow, so a repeat event joins it
const WF = { vehicle: 'OtrVehicleWf01', journey: 'OtrJourneyWf01', destination: 'OtrDestinationWf01', tracking: 'OtrTrackingWf01',
  incident: 'OtrIncidentWf01', documents: 'OtrDocumentsWf01', expenses: 'OtrExpensesWf01', general: 'OtrGeneralWf01' };
const ORDER = ['incident', 'vehicle', 'documents', 'destination', 'journey', 'tracking', 'expenses', 'general'];
const ROOT = ['vehicle', 'documents', 'destination', 'incident'];
const n = $('Normalize').first().json;
const k = $('Classify').first().json;
const ctx = $('Get context').first().json;
const YES = ctx.settings?.glide_routing ?? 0.5; // ponytail: placeholder GLiDE cut-off from the Settings page; tune on labelled events
const g = $('GLiDE').isExecuted && $('GLiDE').first().json.answers ? $('GLiDE').first().json : null; // a failed call counts as unavailable
const p = (q) => (g && g.answers && g.answers[q] ? Number(g.answers[q].noul) : null);
const timeline = ctx.case_timeline || [];
const closes = timeline.filter((t) => t.kind === 'closed').length;
const lastClose = Math.max(0, ...timeline.filter((t) => t.kind === 'closed').map((t) => t.id));
const lastRoute = timeline.filter((t) => t.kind === 'route' && t.id > lastClose).slice(-1)[0];
const openWfs = lastRoute ? String(lastRoute.source_ref || '').replace(/^route:/, '').split(',').filter((w) => WF[w]) : [];

const set = new Set(k.code_workflows);
const scores = {};
for (const q of ['vehicle', 'journey', 'destination', 'tracking', 'incident', 'documents', 'expenses', 'driver_cannot_continue']) {
  scores[q] = p(q);
  if (q !== 'driver_cannot_continue' && scores[q] !== null && scores[q] >= YES) set.add(q);
}
const cannot = scores.driver_cannot_continue !== null && scores.driver_cannot_continue >= YES;
if (set.delete('driver_availability')) set.add(cannot ? 'incident' : 'journey');
if (cannot) set.add('incident');
const dropped = ROOT.some((w) => set.has(w)) && set.delete('journey');
let why;
const named = n.workflows.filter((x) => WF[x]);
if (named.length) { set.clear(); named.forEach((x) => set.add(x)); why = 'the wake-up names its workflows'; }
else if (n.kind === 'follow_up') { set.clear(); (openWfs.length ? openWfs : ['general']).forEach((w) => set.add(w)); why = 'follow-up goes back to the workflows already on the case'; }
else if (!set.size) { set.add('general'); why = 'no problem category matched: general workflow (asks a person when unclear)'; }
const workflows = ORDER.filter((w) => set.has(w));
const joined = workflows.filter((w) => openWfs.includes(w));
const glideTxt = Object.entries(scores).filter(([, v]) => v !== null && v >= 0.3).map(([q, v]) => `${q} ${v.toFixed(2)}`).join(', ');
const route_text = `Routed to: ${workflows.join(', ')}. ` + [
  k.codes.length && `codes: ${k.codes.join(', ')}`,
  g && (glideTxt ? `GLiDE: ${glideTxt}` : 'GLiDE: no category'),
  !g && n.kind !== 'follow_up' && 'GLiDE unavailable, codes only',
  dropped && 'journey dropped: the root-cause workflow handles timing',
  why,
  joined.length && n.kind !== 'follow_up' && `joins the open case for ${joined.join(', ')}`,
].filter(Boolean).join('; ') + '.';
const head = n.kind === 'chat' ? '[operator chat]' : n.kind === 'follow_up' ? '[follow-up from the control room]' : `[event from ${n.source}]`;
const items = workflows.map((w) => ({ workflow: w, workflow_id: WF[w], order_ref: n.order_ref, mode: 'main', run_id: `${n.run_id}:${w}`,
  session_id: `case-${n.order_ref}-${w}-${closes}`,
  input: `${head} Order ${n.order_ref}: ${n.text}\n(Router: you are the ${w} workflow. Also on this event: ${workflows.filter((x) => x !== w).join(', ') || 'none'}.)` }));
return [{ json: { order_ref: n.order_ref, workflows, route_text, items, scores } }];

// Every routing decision is on the timeline; a control-room test switch is logged next to it.
const r = $('Resume').first().json, n = $('Normalize').first().json;
const rows = [{ order_ref: r.order_ref, actor: 'router', kind: 'route', text: r.route_text, source_ref: `route:${r.workflows.join(',')}` }];
if (n.simulate === 'driver_unreachable') rows.push({ order_ref: r.order_ref, actor: 'control room test', kind: 'test_flag', text: 'driver_unreachable', source_ref: 'simulate' });
return rows.map((json) => ({ json }));

// One reply for the operator: each workflow's report under its own heading.
const LABEL = { vehicle: 'Vehicle problems', journey: 'Journey disruptions', destination: 'Destination problems', tracking: 'Tracking problems',
  incident: 'Incident / urgent', documents: 'Documents', expenses: 'Driver expenses', general: 'General' };
const items = $('Split').all().map((x) => x.json);
const outs = $('Run workflow').all().map((x) => x.json);
const parts = items.map((it, k) => `${items.length > 1 ? `### ${LABEL[it.workflow]}\n` : ''}${String(outs[k]?.output || (outs[k]?.error ? 'Workflow failed: ' + (outs[k].error.message || outs[k].error) : '(no reply)'))}`);
const n = $('Normalize').first().json;
return [{ json: { order_ref: n.order_ref, actor: 'agent', kind: 'run_report', text: parts.join('\n\n'), source_ref: `route:${items.map((x) => x.workflow).join(',')}` } }];
// (logged at the end by Log run, after the coordinator)

// Re-plans resume instead of restarting: stages logged since the last close are reused, and GLiDE picks where each
// workflow continues from (a rejection reason, failed booking or new fact can make an earlier stage stale).
// GLiDE sees every event since the last close, not only the newest one. A workflow whose plan lines are still waiting
// for a decision may "keep_plan": it is not run again and the coordinator reuses those lines (only when another workflow runs).
// @include plan.js
const r = $json, n = $('Normalize').first().json, tl = $('Get context').first().json.case_timeline || [];
const lastClose = Math.max(0, ...tl.filter((t) => t.kind === 'closed').map((t) => t.id));
const lastDecision = Math.max(lastClose, ...tl.filter((t) => t.kind === 'decision').map((t) => t.id));
const done = {}, pending = {};
for (const t of tl.filter((t) => t.id > lastClose)) {
  if (t.kind === 'stage') {
    const [, wf, stage] = String(t.source_ref).split(':');
    (done[wf] ||= {})[stage] = { result: String(t.text).replace(/^[^:]+:\s*/, ''), at: t.at };
  }
  if (t.kind === 'plan_draft' && t.id > lastDecision) { try { pending[JSON.parse(t.text).workflow] = true; } catch (e) { /* unreadable draft */ } }
}
const events = tl.filter((t) => t.id > lastClose && ['event', 'telegram_in', 'driver_reply', 'driver_message', 'decision'].includes(t.kind))
  .slice(-15).map((t) => `${t.at || ''} ${t.kind}: ${String(t.text).slice(0, 300)}`);
const ask = r.workflows.filter((x) => done[x] && STAGES[x]);
const canKeep = (x) => pending[x] && r.workflows.length > 1;
const glide_body = { model: 'fastino/GLiDE', store: false,
  state: { new_event: n.text, event_kind: n.kind, events_since_close: events, finished_stages: Object.fromEntries(ask.map((x) => [x, done[x]])) },
  questions: Object.fromEntries(ask.map((x) => [x, { type: 'choice',
    instructions: `The ${x} workflow already finished the stages in finished_stages.${x}. new_event is the newest of events_since_close: a new problem, a failed booking, a rejected plan with a reason, an expired offer or an answer from a person. From which stage must the ${x} workflow continue? Pick the earliest stage whose result new_event makes wrong or stale; if no finished result is affected, pick the first unfinished stage.${canKeep(x) ? ` Pick keep_plan only if new_event changes nothing for the ${x} workflow.` : ''}`,
    criteria: { ...STAGES[x], ...(canKeep(x) ? { keep_plan: `new_event does not touch the ${x} problem; keep its plan lines that wait for a decision` } : {}) } }])) };
return [{ json: { done, ask, pending, glide_body } }];

// Each agent input lists its finished stages and where to continue. Low GLiDE confidence: first unfinished stage (else the last).
// @include plan.js
const r = $('Route').first().json, p = $('Resume prep').first().json, n = $('Normalize').first().json, ctx = $('Get context').first().json;
const CUT = ctx.settings?.glide_resume ?? 0.4; // ponytail: placeholder cut-off from the Settings page
const g = $('GLiDE resume').isExecuted ? $('GLiDE resume').first().json.answers || {} : {};
const resume = {}, kept = [];
let items = r.items.map((it) => {
  const d = p.done[it.workflow];
  if (!d) return it;
  const names = Object.keys(STAGES[it.workflow]), a = g[it.workflow];
  if (a && a.choice === 'keep_plan' && p.pending[it.workflow] && Number(a.confidence) >= CUT) { kept.push(it.workflow); resume[it.workflow] = `keeps its waiting plan lines (GLiDE ${Number(a.confidence).toFixed(2)})`; return null; }
  const trusted = a && names.includes(a.choice) && Number(a.confidence) >= CUT;
  const from = trusted ? a.choice : names.find((s) => !d[s]) || names[names.length - 1];
  resume[it.workflow] = `${from} (${trusted ? 'GLiDE ' + Number(a.confidence).toFixed(2) : 'first unfinished stage'})`;
  const keep = names.slice(0, names.indexOf(from)).filter((s) => d[s]).map((s) => `${s}: ${d[s].result}`);
  return { ...it, input: `${it.input}\nFinished stages (reuse these results, do not ask again): ${keep.join('; ') || 'none'}.\nContinue from stage: ${from}.` };
});
// Every workflow kept: the first one runs anyway (something new happened, so one plan must look at it).
if (!items.some(Boolean)) { const k = kept.shift(); delete resume[k]; items = r.items.map((it) => (it.workflow === k ? it : null)); }
items = items.filter(Boolean);
// Safety line: an incident on a new event gets the 112 message to the driver at once, once per open case.
const tl = ctx.case_timeline || [], lastClose = Math.max(0, ...tl.filter((t) => t.kind === 'closed').map((t) => t.id));
const sentSafety = tl.some((t) => t.id > lastClose && t.kind === 'driver_message' && String(t.text).includes('call 112'));
const safety_line = r.workflows.includes('incident') && n.kind !== 'follow_up' && !n.workflows.length && !sentSafety;
const resumeTxt = Object.entries(resume).map(([x, s]) => (kept.includes(x) ? `${x} ${s}` : `${x} from ${s}`)).join(', ');
return [{ json: { ...r, items, kept, resume, safety_line, route_text: r.route_text + (resumeTxt ? ` Resume: ${resumeTxt}.` : '') + (safety_line ? ' 112 safety line sent to the driver.' : '') } }];

// Marks "this run is merging now", written before the context is read: an older run still finishing leaves its drafts to us.
const n = $('Normalize').first().json;
return [{ json: { order_ref: n.order_ref, actor: 'router', kind: 'coord', text: 'Merging the drafts of this event into one plan.', source_ref: `run:${n.run_id}` } }];

// One plan per order. Skip when a newer event is still being worked on (that run merges our drafts too).
// Live drafts = plan_draft rows since the last close and the last plan decision, latest per workflow; file only if this run added one.
// @include plan.js
const n = $('Normalize').first().json, tl = $json.case_timeline || [];
const lastClose = Math.max(0, ...tl.filter((t) => t.kind === 'closed').map((t) => t.id));
const mine = tl.find((t) => t.kind === 'event' && t.source_ref === `run:${n.run_id}`);
const newer = tl.filter((t) => t.kind === 'event' && mine && t.id > mine.id && !tl.some((c) => c.kind === 'coord' && c.source_ref === t.source_ref));
if (newer.length) return [{ json: { file: false, note: `Merged into the newer run on event #${newer[0].id}; that run files the plan.` } }];
const from = Math.max(lastClose, ...tl.filter((t) => t.kind === 'decision').map((t) => t.id));
const latest = {};
for (const t of tl.filter((t) => t.kind === 'plan_draft' && t.id > from)) {
  try { const d = JSON.parse(t.text); latest[d.workflow] = { ...d, run: t.source_ref }; } catch (e) { /* unreadable draft skipped */ }
}
const drafts = Object.values(latest);
if (!drafts.some((d) => d.run.startsWith(`run:${n.run_id}:`))) return [{ json: { file: false, note: '' } }];
const m = mergeDrafts(drafts);
return [{ json: { file: true, workflows: drafts.map((d) => d.workflow), merged: m, lines: JSON.stringify(m.lines),
  rationale: m.rationale.join(' | '), evidence_refs: [...new Set(m.evidence.join(',').split(',').map((x) => x.trim()).filter(Boolean))].join(','), ready_at: m.ready_at } }];

// One writer call: the workflows' drafts become one buyer message, one delivery-contact message and one driver note.
// Facts come only from the checked plan preview (prices, arrival times in the buyer's local time, offer deadline).
const p = $json, k = $('Coordinate').first().json, m = k.merged, plan = p.plan;
const need = { buyer: plan.needs_buyer || m.customer.length > 0, contact: Boolean(p.delivery_contact?.name) && (m.contact.length > 0 || plan.steps.some((x) => x.kind === 'change_delivery_window') || plan.options.some((o) => o.steps.some((x) => x.kind === 'change_delivery_window'))) };
const prompt = `You write messages for Bahn Express, a company that delivers cars by driving them. A Bahn employee reads and approves every message before it is sent.
Use ONLY the facts below. Never invent a time, price, place or promise. Times for the buyer and the delivery contact are in their local time as written below. Plain, short, polite English.

PLAN (checked by code): ${p.summary}
Current delivery window: ${p.window_was || 'not set'}
Options for the buyer: ${plan.options.length ? plan.options.map((o) => `${o.key} (${o.names.join('/')}): arrives ${o.arrives_local}, ${o.on_time === false || o.late_hours > 0 ? o.late_hours + ' h later than the earliest' : 'earliest'}, total EUR ${o.total_eur}`).join('; ') + (plan.recommended ? `. Recommended: ${plan.recommended}` : '') : 'none'}
Offer valid until: ${plan.valid_until_local || 'not set yet (the system adds the reply-by line when the offer is sent; do not mention any deadline)'}
Plan lines: ${plan.steps.map((x) => `${x.kind}: ${x.detail}`).join(' | ')}
Buyer: ${p.buyer}. Delivery contact: ${p.delivery_contact ? `${p.delivery_contact.name} (${p.delivery_contact.role || 'delivery place'})` : 'none'}
Drafts from the workflows (merge them, drop repeats): buyer: ${m.customer.join(' /// ') || 'none'}; delivery contact: ${m.contact.join(' /// ') || 'none'}; driver notes: ${m.lines.filter((l) => l.kind === 'notify_driver').map((l) => l.detail).join(' /// ') || 'none'}

Write:
- customer_message: ${need.buyer ? 'to the buyer: what happened in one sentence, then each option with its letter, local arrival time and total price, which one we recommend, and the offer deadline; ask them to reply with the letter. If there are no options, ask the question from the drafts.' : 'empty string (the buyer needs no message)'}
- delivery_contact_message: ${need.contact ? 'to the delivery contact: the new expected arrival in their local time, asking them to confirm they can receive the car then. If there are options, say the final time follows once the buyer has chosen.' : 'empty string'}
- driver_note: the instruction for the driver, sent only after the plan is approved (and the buyer has chosen, when there are options). Facts and actions only, one or two sentences. Empty string if the driver needs nothing.

Answer with JSON only: {"customer_message": "...", "delivery_contact_message": "...", "driver_note": "..."}`;
return [{ json: { prompt, need } }];

// Parse the writer's JSON; if it fails, the workflows' own drafts are used as they are.
const k = $('Coordinate').first().json, m = k.merged, need = $('Writer prompt').first().json.need;
let o = {};
try { o = JSON.parse(String($json.text || '').replace(/^[^{]*/, '').replace(/[^}]*$/, '')); } catch (e) { o = {}; }
const pick = (v, fallback) => (typeof v === 'string' && v.trim() ? v.trim() : fallback);
const customer = need.buyer ? pick(o.customer_message, m.customer.join('\n\n')) : '';
const contact = need.contact ? pick(o.delivery_contact_message, m.contact.join('\n\n')) : '';
const driver = pick(o.driver_note, '');
const lines = m.lines.filter((l) => l.kind !== 'notify_driver' && l.kind !== 'customer_message' && l.kind !== 'delivery_contact_message');
if (driver) lines.push({ kind: 'notify_driver', detail: driver });
else lines.push(...m.lines.filter((l) => l.kind === 'notify_driver'));
  // Fact check by code: every time (HH:MM) and EUR amount in the messages must appear in the plan facts the writer got.
  const facts = $('Writer prompt').first().json.prompt.split('Drafts from the workflows')[0];
  const num = (x) => Number(String(x).replace(/[^\d.,]/g, '').replace(/[.,]+$/, '').replace(/,(\d{3})/g, '$1').replace(',', '.'));
  const factNums = new Set((facts.match(/\d[\d,.]*/g) || []).map(num));
  const factTimes = new Set((facts.match(/(?<!\d)\d{1,2}[:.]\d{2}(?!\d)/g) || []).map((t) => t.replace('.', ':').padStart(5, '0')));
  const said = [customer, contact, driver].join('\n');
  const badTimes = (said.match(/(?<!\d)\d{1,2}[:.]\d{2}(?!\d)/g) || []).filter((t) => !factTimes.has(t.replace('.', ':').padStart(5, '0')));
  const badEur = (said.match(/(?:EUR|€)\s?\d[\d,.]*|\d[\d,.]*\s?(?:EUR|€)/g) || []).filter((x) => !factNums.has(num(x)));
  const code_problems = [...badTimes.map((t) => `time ${t}`), ...badEur.map((x) => `amount ${x}`)];
  const glide_body = { model: 'fastino/GLiDE', store: false, state: { facts: facts.replace(/^[\s\S]*?(?=PLAN \(checked by code\))/, ''), messages: `To buyer: ${customer || '(none)'}\nTo delivery contact: ${contact || '(none)'}\nTo driver: ${driver || '(none)'}` },
    questions: { grounded: { type: 'noul', instructions: 'Is every time, date, price, place and promise in messages backed by facts (nothing invented, nothing changed)?', criteria: { true: 'Everything is in the facts', false: 'Something is not in the facts' } } } };
return [{ json: { code_problems, glide_body, lines: JSON.stringify(lines), customer_message: customer, delivery_contact_message: contact, wrote: Boolean(o.customer_message || o.driver_note) } }];

// The run report (one heading per workflow) plus what the coordinator did; logged last so the control room shows it.
const r = $('Collect').first().json, k = $('Coordinate').first().json;
const ran = (x) => $(x).isExecuted ? $(x).first().json : null;
const pre = ran('Preview'), filed = ran('File plan');
const line = !k.file ? k.note
  : pre && !pre.ok ? `Combined plan NOT filed (${k.workflows.join(' + ')}): ${pre.error}`
  : filed && filed.created ? `One plan filed for a person (${k.workflows.join(' + ')}): proposal #${filed.proposal_id}${filed.replaced?.length ? `, replaces #${filed.replaced.join(', #')}` : ''}. ${pre.summary}`
  : `Combined plan NOT filed (${k.workflows.join(' + ')}): ${filed?.error || 'no answer from propose_plan'}`;
return [{ json: { ...r, text: r.text + (line ? `\n\n### Plan\n${line}` : '') } }];

// Staff see a warning on the plan when a time or price in a message is not in the plan facts. The person still decides.
const wr = $('Writer result').first().json, S = $('Context after').first().json.settings || {};
const g = $json.answers?.grounded, cut = Number(S.glide_grounding ?? 0.05);
const problems = [...wr.code_problems];
if (g && Number(g.noul) < cut) problems.push(`GLiDE ${Number(g.noul).toFixed(2)} says something is not in the plan facts`);
const { glide_body, code_problems, ...rest } = wr;
return [{ json: { ...rest, fact_note: problems.length ? `Fact check warning - check the messages: ${problems.join('; ')}` : '' } }];

// The driver hears that a plan is being decided and keeps to the current one (a status, not a new instruction).
const f = $json;
if (!f.created) return [];
return [{ json: { order_ref: $('Normalize').first().json.order_ref, text: 'Bahn is deciding on a change for this delivery. Keep to your current plan until we confirm.' } }];
